<script lang="ts">
 import type {Entity,VaultSnapshot} from '../../lib/types';
 import {newId,nowIso} from '../../lib/types';
 import {saveSnapshot} from '../../lib/api';
 import {ASSETS,money,formatMoney,units,negate,subtract,total,type Money} from '../../domain/money';
 import {makeEntry,dateToday,accountBalances,reconciliation,ledgerCsv,preferences,validateLedger,type LedgerAccount,type Transaction,type FinanceRecord} from '../../domain/ledger';
 import {emptyProposal,localLedgerProposal,legacyCosts} from '../../domain/finance-capture';
 import {monthlyCosts,periodReport,expectedPayments,orderReport,field} from '../../domain/reports';
 import type {Proposal} from '../../domain/proposal';
 import InvestmentPanel from './InvestmentPanel.svelte';
 import MoneyGraph from './MoneyGraph.svelte';
 import {parseFinance,parseFinanceQuery} from '../../ai/finance';
 import type {ProviderConfig} from '../../ai/provider';
 import {queryLedger,type LedgerQuery} from '../../domain/reports';
 export let snapshot:VaultSnapshot;
 export let config:ProviderConfig;
 export let saved:(next:VaultSnapshot)=>void;
 export let stage:(raw:string,proposal:Proposal)=>Promise<void>;
 export let edit:(entity?:Entity)=>void;
 let tab='流水',month=dateToday().slice(0,7),search='',accountFilter='',projectFilter='',scrollTop=0,form='',busy=false,error='',sentence='';
 let kind:Transaction['kind']='SPEND',amount='',asset='CNY',accountId='',counterId='',date=dateToday(),note='',payee='',projectId='',resourceId='',orderId='',fee='',feeAccountId='';
 let accountName='',accountKind:LedgerAccount['kind']='ASSET',linkedEntity='',parentId='',editingAccount='',actual='',reason='';
 let resource='',effectiveFrom=dateToday(),allocationShares:Array<{projectId:string;weight:number}>=[];
 let budget='',budgetProject='',week=false,entryId='';
 let question='',interpreted:LedgerQuery|undefined;
 $: answer=interpreted?periodReport({...snapshot,transactions:queryLedger(snapshot,interpreted)},interpreted.from,interpreted.to):undefined;
 let lotMethod:'FIFO'|'LIFO'='FIFO',showEntries=false,taxRate=0,reserveAccountId='';
 $: settings=preferences(snapshot);
 $: if(settings){lotMethod=settings.lotMethod;showEntries=settings.showEntries;taxRate=settings.taxRate*100;reserveAccountId=settings.reserveAccountId??'';}
 $: accounts=(snapshot.ledgerAccounts??[]).filter(a=>a.privacy!=='SECRET');
 $: activeAccounts=accounts.filter(a=>!a.archived);
 $: funds=activeAccounts.filter(a=>['ASSET','LIABILITY'].includes(a.kind)&&a.asset===asset);
 $: counters=activeAccounts.filter(a=>a.id!==accountId&&(!a.asset||a.asset===asset)&&(kind==='TRANSFER'?['ASSET','LIABILITY'].includes(a.kind):a.kind===(kind==='INCOME'?'INCOME':kind==='OPENING'?'EQUITY':'EXPENSE')));
 $: projects=snapshot.entities.filter(e=>e.category==='Project'&&e.privacy!=='SECRET');
 $: resources=snapshot.entities.filter(e=>['Subscription','Server','Domain','AI Provider Account'].includes(e.category)&&e.privacy!=='SECRET');
 $: orders=snapshot.entities.filter(e=>e.category==='Order'&&e.privacy!=='SECRET');
 $: balances=accountBalances(snapshot);
 $: from=week?new Date(Date.now()-6*86400000).toLocaleDateString('sv-SE'):`${month}-01`;
 $: to=week?dateToday():`${month}-31`;
 $: report=periodReport(snapshot,from,to);
 $: costs=monthlyCosts(snapshot,`${month}-01`);
 $: expected=expectedPayments(snapshot,month);
 $: legacy=legacyCosts(snapshot);
 $: rows=report.transactions.filter(t=>t.privacy!=='SECRET'&&(!accountFilter||t.legs.some(l=>l.accountId===accountFilter))&&(!projectFilter||t.legs.some(l=>l.projectId===projectFilter))&&`${t.note??''} ${t.payee??''} ${t.legs.map(l=>accounts.find(a=>a.id===l.accountId)?.name).join(' ')}`.toLowerCase().includes(search.toLowerCase())).sort((a,b)=>b.occurredAt.localeCompare(a.occurredAt)||b.createdAt.localeCompare(a.createdAt));
 $: start=Math.max(0,Math.floor(scrollTop/76)-4);
 $: visible=rows.slice(start,start+18);
 $: reversed=new Set(snapshot.transactions?.map(t=>t.reversalOf));
 const list=(values:Money[])=>values.length?values.map(formatMoney).join(' · '):'—';
 const accountLabel=(id:string)=>accounts.find(a=>a.id===id)?.name??id;
 const kindLabel=(value:string)=>({SPEND:'支出',INCOME:'收入',TRANSFER:'转账',OPENING:'期初',ADJUST:'调整',TRADE:'交易'}[value]??value);
 const accountKinds={ASSET:'资产',LIABILITY:'负债',INCOME:'收入分类',EXPENSE:'支出分类',EQUITY:'期初与调整'};
 function transactionAmount(t:Transaction){const classified=t.legs.filter(l=>['INCOME','EXPENSE'].includes(accounts.find(a=>a.id===l.accountId)?.kind??''));return list(total((classified.length?classified:t.legs.filter(l=>units(l.money)>0n)).map(l=>l.money.amount.startsWith('-')?negate(l.money):l.money)));}
 async function run(fn:()=>Promise<void>){if(busy)return;busy=true;error='';try{await fn();}catch(e){error=e instanceof Error?e.message:String(e);}finally{busy=false;}}
 async function persist(next:VaultSnapshot){validateLedger(next,snapshot);saved(await saveSnapshot(next));form='';}
 async function submit(){await run(async()=>{
  const account=accounts.find(a=>a.id===accountId);if(!account)throw new Error('请选择账户');
  const t=makeEntry({kind,amount:money(amount,asset),accountId,counterId,date,note,payee,projectId,resourceId,orderId,fee:fee?money(fee,asset):undefined,feeAccountId,taxRate:kind==='INCOME'?taxRate/100:undefined,reserveAccountId});
  if((snapshot.financeRecords??[]).some(r=>r.type==='reconciliation'&&r.accountId===accountId&&r.date>=date)&&!window.confirm('这笔记录早于已对账日期，仍然入账？'))return;
  const raw=`${date} ${kindLabel(kind)} ${formatMoney(money(amount,asset))} ${account.name} ${note}${fee?` 手续费 ${fee} ${asset}`:''}`;const p=emptyProposal();p.financeActions=[{type:'ledger.add',transaction:t,evidence:raw}];await stage(raw,p);form='';amount='';note='';
 });}
 async function setup(){await run(async()=>{const p=emptyProposal();p.financeActions=[{name:'现金',kind:'ASSET',asset:'CNY'},{name:'其他支出',kind:'EXPENSE'},{name:'其他收入',kind:'INCOME'},{name:'手续费',kind:'EXPENSE'},{name:'期初与调整',kind:'EQUITY'}].map(a=>({type:'account.add',account:{...a,id:newId('account'),privacy:'PRIVATE'} as LedgerAccount}));await stage('创建我的账本账户',p);});}
 async function addAccount(){await run(async()=>{const account:LedgerAccount={id:editingAccount||newId('account'),name:accountName.trim(),kind:accountKind,asset:['ASSET','LIABILITY'].includes(accountKind)?asset:undefined,privacy:'PRIVATE',entityRef:linkedEntity||undefined,parentId:parentId||undefined};if(editingAccount){const next=structuredClone(snapshot);next.ledgerAccounts=next.ledgerAccounts?.map(a=>a.id===editingAccount?account:a);await persist(next);}else{const p=emptyProposal();p.financeActions=[{type:'account.add',account}];await stage(`新增账户 ${account.name}`,p);form='';}});}
 async function reverse(t:Transaction){await run(async()=>{const p=emptyProposal();p.financeActions=[{type:'ledger.reverse',transactionId:t.id,id:newId('tx'),idempotencyKey:newId('reverse'),occurredAt:dateToday()}];await stage(`冲正 ${t.note??t.payee??t.id}`,p);});}
 async function reconcile(){await run(async()=>{const next=structuredClone(snapshot);const result=reconciliation(next,accountId,money(actual,asset),date,reason);if(result.transaction&&!window.confirm(`差额 ${formatMoney(result.transaction.legs[0].money)}，记为调整？`))return;next.transactions=[...next.transactions??[],...result.transaction?[result.transaction]:[]];next.financeRecords=[...next.financeRecords??[],result.record];await persist(next);});}
 async function allocate(){await run(async()=>{const next=structuredClone(snapshot);const old=next.allocationRules?.find(r=>r.resourceId===resource&&!r.effectiveTo);if(old){if(effectiveFrom<dateToday())throw new Error('新版本不能改写过去的分摊');old.effectiveTo=effectiveFrom;}next.allocationRules=[...next.allocationRules??[],{id:newId('allocation'),resourceId:resource,effectiveFrom,shares:allocationShares.map(r=>({projectId:r.projectId,weight:r.weight/100}))}];await persist(next);});}
 async function saveBudget(){await run(async()=>{const next=structuredClone(snapshot),id=`budget:${month}:${asset}:${budgetProject}`;next.financeRecords=[...next.financeRecords?.filter(r=>r.id!==id)??[],{id,type:'budget',month,value:money(budget,asset),projectId:budgetProject||undefined}];await persist(next);});}
 async function savePreferences(){await run(async()=>{const next=structuredClone(snapshot);next.financeRecords=[...next.financeRecords?.filter(r=>r.type!=='preferences')??[],{id:settings?.id??newId('finance-settings'),type:'preferences',lotMethod,showEntries,taxRate:taxRate/100,reserveAccountId:reserveAccountId||undefined}];await persist(next);});}
 async function parseSentence(useModel=false){await run(async()=>{const p=useModel?await parseFinance(config,sentence,snapshot):localLedgerProposal(sentence,snapshot);if(!p)throw new Error('请写明收支、金额、币种与账户');await stage(sentence,p);sentence='';});}
 function csv(){if(!window.confirm('导出明文 CSV？文件包含本页流水的金额、账户和备注。'))return;const url=URL.createObjectURL(new Blob([ledgerCsv(snapshot,rows)],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=`Relakeep-${month}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
 function openEntry(){form='entry';if(!funds.some(a=>a.id===accountId))accountId=funds[0]?.id??'';if(!counters.some(a=>a.id===counterId))counterId=counters[0]?.id??'';feeAccountId=activeAccounts.find(a=>a.name==='手续费')?.id??'';}
</script>

<section class="ledger-page">
 <header class="ledger-heading"><div><span class="eyebrow">RELAKEEP / LEDGER</span><h1>账本</h1></div><div class="button-row"><label class="month-picker"><span class="sr-only">月份</span><input type="month" bind:value={month} on:change={()=>scrollTop=0} /></label><button class="primary" on:click={openEntry}>记一笔</button></div></header>
 <nav class="ledger-tabs" aria-label="账本视图">{#each ['流水','资源成本','项目','回顾','投资','账户'] as item}<button class:active={tab===item} on:click={()=>{tab=item;form='';}}>{item}</button>{/each}</nav>
 {#if error}<p class="error" role="alert">{error}</p>{/if}
 {#if !accounts.length}<div class="ledger-empty"><h2>从第一个账户开始</h2><button class="primary" disabled={busy} on:click={setup}>建立账本</button><button class="text-button" on:click={()=>{form='account';editingAccount='';}}>自定义账户</button></div>{/if}

 {#if form==='entry'}<form class="ledger-form" on:submit|preventDefault={submit}>
  <div class="section-heading"><h2>记一笔</h2><button type="button" class="text-button" on:click={()=>form=''}>关闭</button></div>
  <div class="form-grid"><label>类型<select bind:value={kind} on:change={()=>counterId=''}><option value="SPEND">支出</option><option value="INCOME">收入</option><option value="TRANSFER">转账</option><option value="OPENING">期初余额</option></select></label><label>金额<input bind:value={amount} required inputmode="decimal" /></label><label>币种<select bind:value={asset} on:change={()=>{accountId='';counterId='';}}>{#each ASSETS as a}<option value={a.code}>{a.code}</option>{/each}</select></label><label>日期<input type="date" bind:value={date} required /></label>
   <label>{kind==='INCOME'||kind==='OPENING'?'收款账户':'付款账户'}<select bind:value={accountId} required><option value="">选择账户</option>{#each funds as a}<option value={a.id}>{a.name}</option>{/each}</select></label><label>{kind==='TRANSFER'?'转入账户':'分类'}<select bind:value={counterId} required><option value="">选择</option>{#each counters as a}<option value={a.id}>{a.name}</option>{/each}</select></label><label>项目<select bind:value={projectId}><option value="">无</option>{#each projects as p}<option value={p.id}>{p.name}</option>{/each}</select></label><label>资源<select bind:value={resourceId}><option value="">无</option>{#each resources as r}<option value={r.id}>{r.name}</option>{/each}</select></label>
   {#if kind==='INCOME'}<label>订单<select bind:value={orderId}><option value="">无</option>{#each orders as o}<option value={o.id}>{o.name}</option>{/each}</select></label><label>平台手续费<input bind:value={fee} inputmode="decimal" /></label>{#if fee}<label>手续费分类<select bind:value={feeAccountId} required><option value="">选择</option>{#each activeAccounts.filter(a=>a.kind==='EXPENSE') as a}<option value={a.id}>{a.name}</option>{/each}</select></label>{/if}{/if}
   <label>对方<input bind:value={payee} maxlength="500" /></label><label>备注<input bind:value={note} maxlength="5000" /></label>
  </div><button class="primary" disabled={busy}>预览</button>
 </form>{/if}
 {#if form==='account'}<form class="ledger-form" on:submit|preventDefault={addAccount}><div class="section-heading"><h2>{editingAccount?'编辑账户':'添加账户'}</h2><button type="button" class="text-button" on:click={()=>form=''}>关闭</button></div><div class="form-grid"><label>名称<input bind:value={accountName} required /></label><label>类型<select bind:value={accountKind} disabled={!!editingAccount}>{#each Object.entries(accountKinds) as [value,label]}<option value={value}>{label}</option>{/each}</select></label>{#if ['ASSET','LIABILITY'].includes(accountKind)}<label>币种<select bind:value={asset} disabled={!!editingAccount}>{#each ASSETS as a}<option value={a.code}>{a.code}</option>{/each}</select></label>{/if}<label>关联资产<select bind:value={linkedEntity}><option value="">无</option>{#each snapshot.entities.filter(e=>e.privacy!=='SECRET') as e}<option value={e.id}>{e.name}</option>{/each}</select></label><label>上级分类<select bind:value={parentId}><option value="">无</option>{#each activeAccounts.filter(a=>a.id!==editingAccount) as a}<option value={a.id}>{a.name}</option>{/each}</select></label></div><button class="primary" disabled={busy}>{editingAccount?'保存':'预览'}</button></form>{/if}
 {#if form==='reconcile'}<form class="ledger-form" on:submit|preventDefault={reconcile}><h2>对账 · {accountLabel(accountId)}</h2><div class="form-grid"><label>实际余额 · {asset}<input bind:value={actual} required inputmode="decimal" /></label><label>截至日期<input type="date" bind:value={date} required /></label><label>差额原因<input bind:value={reason} /></label></div><button class="primary" disabled={busy}>核对并保存</button><button type="button" class="text-button" on:click={()=>form=''}>取消</button></form>{/if}

 {#if tab==='流水'}
  <div class="ledger-totals"><div><span>本月支出</span><strong>{list(report.expense)}</strong></div><div><span>本月收入</span><strong>{list(report.income)}</strong></div><div><span>固定月成本</span><strong>{list(costs.totals)}</strong></div></div>
  <form class="sentence-entry" on:submit|preventDefault={()=>parseSentence()}><input aria-label="一句话记账" bind:value={sentence} placeholder="今天花了八块，现金付的" required /><button class="secondary" disabled={busy}>预览</button><button type="button" class="text-button" disabled={busy||!sentence.trim()} on:click={()=>parseSentence(true)}>AI 整理</button></form>
  <div class="ledger-filters"><input type="search" aria-label="搜索流水" bind:value={search} placeholder="搜索流水" on:input={()=>scrollTop=0} /><select bind:value={accountFilter} aria-label="账户筛选" on:change={()=>scrollTop=0}><option value="">全部账户</option>{#each accounts as a}<option value={a.id}>{a.name}</option>{/each}</select><select bind:value={projectFilter} aria-label="项目筛选" on:change={()=>scrollTop=0}><option value="">全部项目</option>{#each projects as p}<option value={p.id}>{p.name}</option>{/each}</select><button class="text-button" on:click={csv}>导出 CSV</button></div>
  <div class="ledger-scroll" on:keydown={e=>{if(e.key==="ArrowDown")e.currentTarget.scrollTop+=76;if(e.key==="ArrowUp")e.currentTarget.scrollTop-=76;}} on:scroll={e=>scrollTop=e.currentTarget.scrollTop} role="region" aria-label="流水列表" tabindex="0"><div style:height={`${rows.length*76}px`} style:position="relative"><div style:transform={`translateY(${start*76}px)`}>{#each visible as t,i (t.id)}<div class="transaction-row"><time>{start+i===0||rows[start+i-1]?.occurredAt!==t.occurredAt?t.occurredAt.slice(5):''}</time><button class="transaction-title" on:click={()=>entryId=entryId===t.id?'':t.id}><strong>{t.note||t.payee||kindLabel(t.kind)}</strong><small>{t.reversalOf?'冲正':kindLabel(t.kind)} · {accountLabel(t.legs[0].accountId)}{#if snapshot.financeRecords?.some(r=>r.type==='reconciliation'&&r.date>=t.occurredAt&&r.createdAt<t.createdAt)} · 回溯{/if}</small></button><strong class="numeric">{transactionAmount(t)}</strong><button class="text-button" disabled={busy||!!t.reversalOf||reversed.has(t.id)} on:click={()=>reverse(t)}>{reversed.has(t.id)?'已冲正':'冲正'}</button></div>{/each}</div></div>{#if !rows.length}<div class="empty-state">这个月还没有流水</div>{/if}</div>
  {#if entryId}{@const entry=rows.find(t=>t.id===entryId)}{#if entry}<div class="ledger-form"><h3>{entry.note||kindLabel(entry.kind)}</h3><p>{entry.occurredAt} · {entry.payee??''}</p>{#each entry.legs as leg}<div class="report-row"><span>{accountLabel(leg.accountId)}</span><strong>{formatMoney(leg.money)}</strong></div>{/each}<button class="text-button" on:click={()=>entryId=''}>收起</button></div>{/if}{/if}
 {:else if tab==='资源成本'}
  <div class="section-heading"><h2>{list(costs.totals)}<small> / 月</small></h2><button class="secondary" on:click={()=>edit()}>添加资源</button></div>
  {#each costs.rows as row}<button class="cost-row" on:click={()=>edit(row.entity)}><span><strong>{row.entity.name}</strong><small>{row.usage?'按量':String(field(row.entity,'billing_period')??'monthly')==='yearly'?'年付':'周期费用'}</small></span><span class="numeric">{formatMoney(row.usage?row.fee:row.monthly)}{row.usage?'':' / 月'}</span></button>{/each}
  {#if legacy.length}<h3>旧费用待整理</h3>{#each legacy as item}<div class="report-row"><span>{snapshot.entities.find(e=>e.id===item.entityId)?.name} · {item.text}</span><button class="secondary" disabled={busy} on:click={()=>run(()=>stage(item.text,item.proposal))}>预览转换</button></div>{/each}{/if}
  <h3>预期扣费</h3>{#each expected as row}<div class="report-row"><span>{row.due} · {row.entity.name}</span><strong>{formatMoney(row.expected)}</strong><span>{row.actual?(row.difference&&units(row.difference)!==0n?`差额 ${formatMoney(row.difference)}`:'已匹配'):'待扣费'}</span></div>{:else}<p class="muted">本月没有扣费提醒</p>{/each}
 {:else if tab==='项目'}
  <div class="section-heading"><h2>项目损益</h2><div class="button-row"><button class="secondary" on:click={()=>{form='allocation';effectiveFrom=dateToday();}}>分摊成本</button><button class="secondary" on:click={()=>edit()}>客户 / 订单</button></div></div>
  {#if form==='allocation'}<form class="ledger-form" on:submit|preventDefault={allocate}><div class="form-grid"><label>资源<select bind:value={resource} required><option value="">选择</option>{#each resources as r}<option value={r.id}>{r.name}</option>{/each}</select></label><label>生效日期<input type="date" bind:value={effectiveFrom} required /></label></div>{#each allocationShares as share,i}<div class="ledger-filters"><select aria-label="分摊项目" bind:value={share.projectId} required><option value="">选择项目</option>{#each projects as p}<option value={p.id}>{p.name}</option>{/each}</select><label>占比 %<input type="number" bind:value={share.weight} min="0" max="100" step="0.0001" required /></label><button type="button" class="text-button" on:click={()=>allocationShares=allocationShares.filter((_,j)=>j!==i)}>移除</button></div>{/each}<button type="button" class="secondary" on:click={()=>allocationShares=[...allocationShares,{projectId:'',weight:0}]}>＋ 项目</button><button class="primary" disabled={busy}>保存分摊</button></form>{/if}
  {#each report.projects as p}<article class="project-report"><header><button class="text-button" on:click={()=>edit(snapshot.entities.find(e=>e.id===p.id))}>{p.name}</button><strong>{list(p.profit)}</strong></header><div class="ledger-totals"><div><span>收入</span>{list(p.income)}</div><div><span>直接成本</span>{list(p.direct)}</div><div><span>分摊成本</span>{list(p.allocated)}</div><div><span>停用后可省 / 月</span>{list(p.avoidable)}</div></div>{#if p.ruleIds.length}<details><summary>所用分摊</summary>{#each p.ruleIds as id}{@const rule=snapshot.allocationRules?.find(r=>r.id===id)}<p>{snapshot.entities.find(e=>e.id===rule?.resourceId)?.name} · {rule?.effectiveFrom} 起</p>{/each}</details>{/if}</article>{/each}
  <div class="report-row"><span>闲置容量</span><strong>{list(report.idle)}</strong></div><h3>订单与应收</h3>{#each orders as order}{@const r=orderReport(snapshot,order)}<div class="report-row"><button class="text-button" on:click={()=>edit(order)}>{order.name}</button><span>{r?`报价 ${formatMoney(r.quote)} · 已收 ${formatMoney(r.paid)}`:'报价待填写'}</span><strong>{r?`应收 ${formatMoney(r.due)}`:'—'}</strong><button class="secondary" on:click={()=>{kind='INCOME';orderId=order.id;asset=r?.quote.asset??'CNY';amount=r?.due.amount??'';projectId=String(field(order,'project')??'');openEntry();}}>收款</button></div>{/each}
 {:else if tab==='回顾'}
  <form class="sentence-entry" on:submit|preventDefault={()=>run(async()=>{interpreted=await parseFinanceQuery(config,question,snapshot);})}><input bind:value={question} placeholder="这个月某个项目赚了多少" aria-label="查询账本" required /><button class="secondary" disabled={busy}>查询</button></form>
  {#if answer&&interpreted}<div class="ledger-form"><div class="section-heading"><span>{interpreted.from} — {interpreted.to}</span><button class="text-button" on:click={()=>interpreted=undefined}>收起</button></div><div class="ledger-totals"><div><span>收入</span><strong>{list(answer.income)}</strong></div><div><span>支出</span><strong>{list(answer.expense)}</strong></div><div><span>净收支</span><strong>{list(total([...answer.income,...answer.expense.map(negate)]))}</strong></div></div></div>{/if}
  <div class="section-heading"><h2>{week?'最近七天':month}</h2><div class="button-row"><button class="secondary" on:click={()=>week=!week}>{week?'按月':'最近七天'}</button><button class="secondary" on:click={()=>form='budget'}>设置预算</button></div></div>
  <div class="ledger-totals"><div><span>收入</span><strong>{list(report.income)}</strong></div><div><span>支出</span><strong>{list(report.expense)}</strong></div><div><span>净收支</span><strong>{list(total([...report.income,...report.expense.map(negate)]))}</strong></div></div>
  {#if form==='budget'}<form class="ledger-form" on:submit|preventDefault={saveBudget}><div class="form-grid"><label>预算<input bind:value={budget} required inputmode="decimal" /></label><label>币种<select bind:value={asset}>{#each ASSETS as a}<option value={a.code}>{a.code}</option>{/each}</select></label><label>项目<select bind:value={budgetProject}><option value="">全部</option>{#each projects as p}<option value={p.id}>{p.name}</option>{/each}</select></label></div><button class="primary" disabled={busy}>保存</button></form>{/if}
  {#each snapshot.financeRecords?.filter(r=>r.type==='budget'&&r.month===month)??[] as b}{#if b.type==='budget'}{@const p=report.projects.find(p=>p.id===b.projectId)}{@const spent=total(b.projectId?[...p?.direct??[],...p?.allocated??[]]:report.expense).find(m=>m.asset===b.value.asset)??money('0',b.value.asset)}<div class="report-row"><span>{projects.find(p=>p.id===b.projectId)?.name??'全部'}预算</span><span>{formatMoney(spent)} / {formatMoney(b.value)}</span><strong>{units(spent)>units(b.value)?'超出':'剩余'} {formatMoney(units(spent)>units(b.value)?subtract(spent,b.value):subtract(b.value,spent))}</strong></div>{/if}{/each}
  <MoneyGraph {snapshot} {month} mode="flow" onOpen={id=>edit(snapshot.entities.find(e=>e.id===id))} />
  <h3>续费与差额</h3>{#each expected as row}<div class="report-row"><span>{row.due} · {row.entity.name}</span><span>{row.actual?`实际 ${formatMoney(row.actual)}`:`预计 ${formatMoney(row.expected)}`}</span>{#if row.difference&&units(row.difference)!==0n}<strong>差额 {formatMoney(row.difference)}</strong>{/if}</div>{/each}
 {:else if tab==='投资'}<InvestmentPanel {snapshot} {stage} saved={async next=>{await persist(next);}} />
 {:else if tab==='账户'}
  <div class="section-heading"><h2>账户</h2><button class="secondary" on:click={()=>{form='account';editingAccount='';accountName='';parentId='';linkedEntity='';}}>＋ 账户</button></div>
  {#each accounts as a}<div class="account-row"><button class="text-button" on:click={()=>{form='account';editingAccount=a.id;accountName=a.name;accountKind=a.kind;asset=a.asset??'CNY';linkedEntity=a.entityRef??'';parentId=a.parentId??'';}}><strong>{a.name}</strong><small>{accountKinds[a.kind]}{a.archived?' · 已归档':''}</small></button><strong>{list((balances.get(a.id)??[]).map(m=>a.kind==='LIABILITY'?negate(m):m))}</strong><div class="button-row">{#if a.asset}<button class="secondary" on:click={()=>{form='reconcile';accountId=a.id;asset=a.asset!;actual='';reason='';date=dateToday();}}>对账</button>{/if}<button class="text-button" disabled={busy} on:click={()=>run(async()=>{const next=structuredClone(snapshot);next.ledgerAccounts=next.ledgerAccounts?.map(item=>item.id===a.id?{...item,archived:!a.archived}:item);await persist(next);})}>{a.archived?'启用':'归档'}</button></div></div>{/each}
  <form class="ledger-form" on:submit|preventDefault={savePreferences}><h3>账本设置</h3><div class="form-grid"><label>成本批次<select bind:value={lotMethod}><option value="FIFO">先进先出</option><option value="LIFO">后进先出</option></select></label><label>收入预留 %<input type="number" min="0" max="100" step="0.01" bind:value={taxRate} /></label><label>预留账户<select bind:value={reserveAccountId}><option value="">不预留</option>{#each activeAccounts.filter(a=>a.kind==='ASSET') as a}<option value={a.id}>{a.name}</option>{/each}</select></label><label class="check"><input type="checkbox" bind:checked={showEntries} />显示分录</label></div><button class="primary" disabled={busy}>保存</button></form>
 {/if}
</section>

<style>
 .ledger-page{max-width:1280px;margin:auto}.ledger-heading{display:flex;align-items:center;justify-content:space-between;margin:1rem 0 2rem;gap:1rem}.ledger-heading h1{margin:.25rem 0;font-size:2.6rem}.eyebrow{font-size:.65rem;letter-spacing:.18em;color:var(--muted)}.ledger-tabs{display:flex;gap:1.6rem;border-bottom:1px solid var(--border);margin-bottom:1.5rem;overflow:auto}.ledger-tabs button{background:transparent;padding:1rem 0;color:var(--muted);white-space:nowrap;border-bottom:2px solid transparent}.ledger-tabs .active{color:var(--text);border-color:var(--text)}.ledger-totals{display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));gap:1.5rem;margin:1.5rem 0 2rem}.ledger-totals div{display:flex;flex-direction:column;gap:.5rem}.ledger-totals span{font-size:.8rem;color:var(--muted)}.ledger-totals strong{font-size:1.3rem;font-variant-numeric:tabular-nums;font-weight:550}.ledger-form{padding:1.5rem;border:1px solid var(--border);margin:1rem 0 2rem;background:var(--surface)}.form-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(190px,1fr));gap:1rem;margin-bottom:1rem}.sentence-entry{display:flex;gap:.7rem;margin-bottom:1.5rem}.sentence-entry input{flex:1}.ledger-filters{display:flex;gap:.7rem;align-items:center;margin:1rem 0;flex-wrap:wrap}.ledger-filters input{flex:1;min-width:150px}.ledger-scroll{height:456px;overflow:auto;border-block:1px solid var(--border)}.transaction-row{height:76px;display:grid;grid-template-columns:56px minmax(100px,1fr) auto 60px;gap:1rem;align-items:center;border-bottom:1px solid var(--border)}time{font-size:.8rem;color:var(--muted)}.transaction-title{min-width:0;text-align:left;background:transparent;padding:0}.transaction-title strong{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-weight:550}small{font-size:.75rem;color:var(--muted);display:block}.numeric{font-variant-numeric:tabular-nums;white-space:nowrap}.report-row,.cost-row,.account-row{display:flex;align-items:center;justify-content:space-between;gap:1rem;padding:1.1rem 0;border-bottom:1px solid var(--border);width:100%;text-align:left;background:transparent}.project-report{border-bottom:1px solid var(--border);padding:1rem 0}.project-report header{display:flex;justify-content:space-between;align-items:center}.ledger-empty{padding:2rem 0}.sr-only{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0,0,0,0)}
 @media(max-width:650px){.ledger-heading{align-items:flex-start}.ledger-heading .button-row{flex-direction:column}.ledger-totals{gap:1rem}.ledger-totals strong{font-size:1.05rem}.transaction-row{grid-template-columns:40px minmax(0,1fr) auto;gap:.5rem}.transaction-row>.text-button{display:none}.report-row,.account-row{flex-wrap:wrap}.ledger-tabs{gap:1.2rem}.ledger-form{padding:1rem}.ledger-heading h1{font-size:2rem}}
</style>
